class Solution {
public:
    vector<long long> distance(vector<int>& nums) {
        int n = nums.size();
        unordered_map<int, vector<int>> pos;
        for (int i = 0; i < n; i++) {
            pos[nums[i]].push_back(i);
        }
        vector<long long> arr(n, 0);
        for (auto& [val, indices] : pos) {
            int m = indices.size();
            if (m == 1) continue;
            vector<long long> prefix(m + 1, 0);
            for (int i = 0; i < m; i++) {
                prefix[i + 1] = prefix[i] + indices[i];
            }
            for (int k = 0; k < m; k++) {
                long long idx = indices[k];
                long long left = idx * k - prefix[k];
                long long right = (prefix[m] - prefix[k + 1]) - idx * (m - 1 - k);
                arr[indices[k]] = left + right;
            }
        }
        return arr;
    }
};
